      th_turkuaz: { n: ['Turkuaz Derinlik', 'Turquoise Depth', 'Turkis dybde', 'Profondeur turquoise', 'Profundidad turquesa', 'Profondità turchese'], d: ['Derin okyanus turkuazı — dingin ve berrak bir ışıma.', 'Deep ocean turquoise — a calm, clear glow.', 'Dyp havturkis — en rolig, klar glød.', 'Turquoise océan profond — une lueur calme et claire.', 'Turquesa de océano profundo — un brillo sereno y claro.', 'Turchese oceano profondo — un bagliore calmo e limpido.'] },
