      tr_klasik: { n: ['Klasik Kurdele', 'Classic Ribbon', 'Klassisk bånd', 'Ruban classique', 'Cinta clásica', 'Nastro classico'], d: ['Akışkan kuzey ışığı kurdelesi — varsayılan izin.', 'The flowing northern-light ribbon — your default trail.', 'Det flytende nordlysbåndet — standardsporet ditt.', 'Le ruban d\'aurore fluide — ta traînée par défaut.', 'La cinta fluida de aurora — tu estela por defecto.', 'Il nastro fluido dell\'aurora — la tua scia predefinita.'] },
      tr_yildiz: { n: ['Yıldız Tozu İzi', 'Stardust Trail', 'Stjernestøvspor', 'Traînée de poussière d\'étoiles', 'Estela de polvo estelar', 'Scia di polvere di stelle'], d: ['Arkanda parlayan yıldız tanecikleri bırakırsın.', 'You leave glowing star particles behind you.', 'Du etterlater glødende stjernepartikler.', 'Tu laisses des particules d\'étoiles brillantes derrière toi.', 'Dejas partículas de estrellas brillantes tras de ti.', 'Lasci dietro di te particelle di stelle luminose.'] },
      tr_ikiz: { n: ['İkiz Kurdele', 'Twin Ribbon', 'Tvillingbånd', 'Ruban jumeau', 'Cinta gemela', 'Nastro gemello'], d: ['İzin ikiye ayrılır — altında ikinci, farklı renkte bir kurdele akar.', 'Your trail splits in two — a second, differently colored ribbon flows below.', 'Sporet deles i to — et andre bånd i annen farge flyter under.', 'Ta traînée se divise en deux — un second ruban d\'une autre couleur coule dessous.', 'Tu estela se divide en dos — una segunda cinta de otro color fluye debajo.', 'La tua scia si divide in due — un secondo nastro di colore diverso scorre sotto.'] },
      tr_simsek: { n: ['Şimşek İzi', 'Lightning Trail', 'Lynspor', 'Traînée d\'éclairs', 'Estela de rayos', 'Scia di fulmini'], d: ['İzinin üzerinde çatallanan elektrik kıvılcımları gezinir.', 'Forking electric sparks travel along your trail.', 'Forgrenende elektriske gnister vandrer langs sporet ditt.', 'Des étincelles électriques ramifiées parcourent ta traînée.', 'Chispas eléctricas ramificadas recorren tu estela.', 'Scintille elettriche biforcute percorrono la tua scia.'] },
      tr_buz: { n: ['Buz Kristali', 'Ice Crystal', 'Iskrystall', 'Cristal de glace', 'Cristal de hielo', 'Cristallo di ghiaccio'], d: ['Arkanda süzülerek düşen buz kristalleri bırakırsın.', 'You leave drifting, falling ice crystals behind you.', 'Du etterlater svevende, fallende iskrystaller.', 'Tu laisses des cristaux de glace qui tombent en flottant.', 'Dejas cristales de hielo que caen flotando.', 'Lasci cristalli di ghiaccio che cadono fluttuando.'] },
      tr_alev: { n: ['Alev İzi', 'Flame Trail', 'Flammespor', 'Traînée de flammes', 'Estela de llamas', 'Scia di fiamme'], d: ['İzinden yukarı doğru kor tanecikleri yükselir.', 'Ember particles rise upward from your trail.', 'Glopartikler stiger opp fra sporet ditt.', 'Des braises s\'élèvent de ta traînée.', 'Brasas ascienden desde tu estela.', 'Braci salgono dalla tua scia.'] },
      tr_gokkusagi: { n: ['Gökkuşağı Kurdele', 'Rainbow Ribbon', 'Regnbuebånd', 'Ruban arc-en-ciel', 'Cinta arcoíris', 'Nastro arcobaleno'], d: ['Efsanevi iz: kurdelen tüm renk tayfında dalgalanarak akar.', 'The legendary trail: your ribbon flows waving through the whole spectrum.', 'Det legendariske sporet: båndet bølger gjennom hele fargespekteret.', 'La traînée légendaire : ton ruban ondule à travers tout le spectre.', 'La estela legendaria: tu cinta ondea por todo el espectro.', 'La scia leggendaria: il tuo nastro fluisce ondeggiando in tutto lo spettro.'] }
